-- How the old SSIS package loaded each table.
-- Generated by scripts/make-legacy-manifest.sh from the stand-in ERP's design; see that script.
-- Runs on the warehouse instance.

USE warehouse;
GO

IF SCHEMA_ID('legacy') IS NULL EXEC ('CREATE SCHEMA legacy');
GO
IF OBJECT_ID('legacy.manifest') IS NULL
    CREATE TABLE legacy.manifest (
        table_name   sysname       NOT NULL PRIMARY KEY,
        load_mode    varchar(11)   NOT NULL,  -- full, incremental
        upsert_key   nvarchar(400) NULL,      -- the key the package used; for composite keys, missing a column
        window_days  int           NULL       -- incremental: rows created or modified within this many days
    );
GO

DELETE FROM legacy.manifest;
GO
